const ctx = $('MONTA CONTEXTO TREINO').first().json;

let cliRaw = ($('AGENTE CLIENTE TREINO2').first().json.output || '').trim();
cliRaw = cliRaw.replace(/^```[a-z]*\s*/i,'').replace(/```$/,'').replace(/^["']|["']$/g,'').trim();
const resposta_cliente = cliRaw.split('|||').map(t=>t.trim()).filter(Boolean).join('\n');

let coachRaw = ($input.first().json.output || '').trim();
coachRaw = coachRaw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/,'').trim();

let c = {};
try { c = JSON.parse(coachRaw); }
catch(e) { c = { veredito:'neutro', criterios_tocados:{}, passo_fluxograma:'',
                 feedback:'Não consegui avaliar esta mensagem.', sugestao:'', delta_pontos:0 }; }

let delta = Number(c.delta_pontos || 0);
if (delta > 0.3) delta = 0.3;
if (delta < -0.3) delta = -0.3;

let nova = Number(ctx.nota_parcial || 0) + delta;
nova = Math.max(0, Math.min(10, Math.round(nova * 100) / 100));

return [{ json: {
  ...ctx,
  resposta_cliente,
