function normalizarTelefoneBR(numero){
  if(!numero) return null;
  let n = String(numero).replace(/\D/g,'');
  if(n.length===10){ n='55'+n; n=n.slice(0,4)+'9'+n.slice(4); }
  else if(n.length===11){ n='55'+n; }
  else if(n.length===12 && n.startsWith('55')){ n=n.slice(0,4)+'9'+n.slice(4); }
  else if(!n.startsWith('55')){ const t='55'+n; if(t.length===13) n=t; }
  return n || null;
}

